import{z as s,x as n,o as B,c as o,q as A,j as l,D as a,d as r,s as t,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"打包分发与性能回归","description":"","frontmatter":{"title":"打包分发与性能回归","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-packaging-regression.md","filePath":"llm/edge-packaging-regression.md","lastUpdated":1791413859000}'),d={name:"llm/edge-packaging-regression.md"};function D(p,E,C,m,_,c){const e=n("Mermaid");return B(),o("div",null,[E[2]||(E[2]=A('<h1 id="打包分发与性能回归" tabindex="-1">打包分发与性能回归 <a class="header-anchor" href="#打包分发与性能回归" aria-label="Permalink to &quot;打包分发与性能回归&quot;">​</a></h1><div class="epigraph"><p>模型是资产，分发是供应链：哈希、配对、回滚三件齐了，性能回归门禁才挂得住。</p><footer>—— 据应用商店分发规范与本站开源生态收束课的发布口径整理</footer></div><p><a href="/llm/edge-eval">上一课</a>把评测立成门禁：质量、延迟、资源、持续性四张卷子都要过。本课写门禁挂在哪里——打包与分发链路。模型文件以 GB 计，随应用包分发不现实，首次启动下载是常态；下载、校验、版本配对、灰度、回滚，每一环的失败模式都不崩但变糟，比崩溃难抓得多。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>分发链路五环，每环有坑。体积环：包里只放最小常驻模型，大模型首次启动或按功能下载；应用市场对包体与下载各有历史限制，模型版本还要与应用版本解耦更新，否则一次模型修复要陪一次应用审核。完整性环：mmap 让权重文件被原地读，下载中断、磁盘损坏、被替换的文件直接进计算——校验必须哈希 pin 到发布方，而不是只看下载器报成功。配对环：模型、分词器、运行时三者必须版本配对；分词器错配的失败是「不崩但变蠢」，用户说不清、监控抓不到，是最阴的一类回归。回滚环：新模型灰度出问题，要能几分钟内指回旧版，旧文件与旧配置都要留。节奏环：模型更新走远程配置——新 URL、哈希、灰度比例；应用更新只管运行时。<span class="marginnote">灰度放量就是「先给一小撮人试吃」：新模型先发给 1% 的用户，盯着他们的质量与延迟遥测，没有异常再逐步放大到 10%、50%、100%。它的价值在于把爆炸半径提前锁死——出了问题也只有这一小批用户受影响，且能立刻指回旧版。</span></p>',5)),(B(),l(i,null,{default:a(()=>[t(e,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%8F%91%E5%B8%83%E6%96%B9%E5%87%BA%E5%8C%85%3A%20%E6%A8%A1%E5%9E%8B%20%E5%8A%A0%E5%85%83%E6%95%B0%E6%8D%AE%20%E5%8A%A0%E5%93%88%E5%B8%8C%22%5D%20--%3E%20CDN%5B%22%E9%85%8D%E7%BD%AE%E4%B8%8B%E5%8F%91%3A%20URL%20%E5%8A%A0%E5%93%88%E5%B8%8C%20%E5%8A%A0%E7%81%B0%E5%BA%A6%E6%AF%94%E4%BE%8B%22%5D%0A%20%20CDN%20--%3E%20DL%5B%22%E7%AB%AF%E4%B8%8A%E4%B8%8B%E8%BD%BD%3A%20%E6%96%AD%E7%82%B9%E7%BB%AD%E4%BC%A0%22%5D%0A%20%20DL%20--%3E%20V%7B%22%E5%93%88%E5%B8%8C%E4%B8%8E%E9%85%8D%E5%AF%B9%E6%A3%80%E6%9F%A5%22%7D%0A%20%20V%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20REJ%5B%22%E6%8B%92%E8%BD%BD%20%E5%9B%9E%E9%80%80%E6%97%A7%E7%89%88%22%5D%0A%20%20V%20--%3E%7C%E8%BF%87%7C%20ATOM%5B%22%E5%8E%9F%E5%AD%90%E8%90%BD%E7%9B%98%20%E7%95%99%E6%97%A7%E7%89%88%E6%9C%AC%22%5D%0A%20%20ATOM%20--%3E%20GRAY%5B%22%E7%81%B0%E5%BA%A6%E6%94%BE%E9%87%8F%20%E7%9C%8B%E9%81%A5%E6%B5%8B%E5%88%86%E4%BD%8D%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>发布物三件套：模型文件、元数据（架构、量化配置、分词器版本、最低运行时版本、期望的内存与能耗档）、校验哈希。元数据的字段口径沿用<a href="/llm/eco-map">开源生态收束</a>的发布包清单，把「不可变锚」从发布方仓库延伸到设备端。端上下载器四件事：断点续传；哈希校验后原子落盘，校验不过不进主路径；旧版本保留一份作回滚；加载时启动检查，哈希与分词器版本不匹配就拒载。回归门禁两道：模型变更过上一课的评测矩阵；运行时变更——升后端、换工具链版本——过同一矩阵，运行时同样改数值行为，只测模型等于门只锁了一半。灰度按设备档位分批放量，遥测看真机分位，指标与门禁用同一套。<span class="marginnote">算一笔体积账：一个 4 GB 的模型按 50 Mb/s 的下载速度要约 11 分钟；如果没有断点续传，下载到 99% 时断网就得从头再来——所以「断点续传 加 发布方哈希校验」是 GB 级分发的标配，而不是锦上添花的优化。</span></p><p><span class="marginnote">配对检查写成加载时的硬断言：模型哈希、分词器版本、运行时最低版本三项任一不匹配即拒绝启动并回退——比上线后排查「为什么这批用户觉得模型变笨了」便宜两个数量级。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么哈希与配对是地基：mmap 的性能红利把文件变成计算路径的一部分，文件层的任何损坏或替换都直接进数值；分词器错配不抛异常，只是每个 token 都错一点，只能靠质量遥测的反常分位捞出来，预防比检测便宜。为什么门禁要在设备矩阵跑而不是云端同款：上一课的结论原样适用——数值路径不同，回归只在目标硬件上显形。为什么回滚要留旧文件：配置指回旧版本的前提是旧文件还在设备上，重新下载一个 GB 级文件不是回滚，是二次发布。</p>',5)),(B(),l(i,null,{default:a(()=>[t(e,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E4%B8%80%E6%AC%A1%E5%8F%98%E6%9B%B4%E5%8F%91%E7%94%9F%22%5D%20--%3E%20T%7B%22%E5%8F%98%E4%BA%86%E4%BB%80%E4%B9%88%3F%22%7D%0A%20%20T%20--%3E%7C%22%E6%A8%A1%E5%9E%8B%E6%96%87%E4%BB%B6%22%7C%20G1%5B%22%E9%97%A8%E7%A6%81%E4%B8%80%3A%20%E8%AF%84%E6%B5%8B%E7%9F%A9%E9%98%B5%20%E5%85%A8%E9%87%8F%E5%8D%B7%22%5D%0A%20%20T%20--%3E%7C%22%E8%BF%90%E8%A1%8C%E6%97%B6%E6%88%96%E5%B7%A5%E5%85%B7%E9%93%BE%22%7C%20G2%5B%22%E9%97%A8%E7%A6%81%E4%BA%8C%3A%20%E5%90%8C%E4%B8%80%E7%9F%A9%E9%98%B5%3Cbr%2F%3E%E5%9C%A8%E8%AE%BE%E5%A4%87%E7%9F%A9%E9%98%B5%E4%B8%8A%E8%B7%91%22%5D%0A%20%20T%20--%3E%7C%22%E8%BF%9C%E7%A8%8B%E9%85%8D%E7%BD%AE%22%7C%20G3%5B%22%E5%93%88%E5%B8%8C%E4%B8%8E%E9%85%8D%E5%AF%B9%E5%AD%97%E6%AE%B5%E8%87%AA%E6%A3%80%22%5D%0A%20%20G1%20--%3E%20GR%5B%22%E7%81%B0%E5%BA%A6%3A%201%25%20%E8%B5%B7%E6%AD%A5%22%5D%0A%20%20G2%20--%3E%20GR%0A%20%20G3%20--%3E%20GR%0A%20%20GR%20--%3E%7C%22%E9%81%A5%E6%B5%8B%E5%BC%82%E5%B8%B8%22%7C%20RB%5B%22%E6%8C%87%E5%9B%9E%E6%97%A7%E7%89%88%3A%20%E6%97%A7%E6%96%87%E4%BB%B6%E8%BF%98%E5%9C%A8%E8%AE%BE%E5%A4%87%E4%B8%8A%22%5D%0A%20%20GR%20--%3E%7C%22%E6%AD%A3%E5%B8%B8%22%7C%20FULL%5B%22%E9%80%90%E6%AD%A5%E6%94%BE%E9%87%8F%E8%87%B3%E5%85%A8%E9%87%8F%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>模型加密与 DRM 不在本课：它防不了越狱设备，也与开放权重生态相抵触，工程上通常止步于哈希与签名。应用商店审核细节与各市场政策差异不展开。A/B 实验的统计功效不展开，灰度只按「先小批后放量」的工程口径走。<span class="marginnote">初学者容易以为「模型加密了就不会被人拿走」。实际上模型运行时终要在内存里解密成明文权重，越狱设备可以直接抓取；加密防的是大规模脚本批量拉取，防不了本地提取。所以分发安全的主战场在哈希与签名（防篡改），而不是加密（防提取）。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型与应用版本解耦：模型走配置下发，运行时随应用走。</li><li>三件套发布物加哈希 pin；校验后原子落盘，旧版留一份作回滚。</li><li>加载时硬断言配对：哈希、分词器版本、最低运行时，不符即拒载。</li><li>门禁两道：模型变更与运行时变更过同一评测矩阵，灰度按档位放量。</li><li>出处：应用商店分发规范；本站开源生态收束课的发布包口径；按本课程工程实践整理。</li></ul>',4))])}const T=s(d,[["render",D]]);export{F as __pageData,T as default};
